import type { Goal } from "./schema";
import type { TargetWeightRecommendation } from "./recommenders";

/**
 * Natural Vietnamese responses composed from STRUCTURED facts (belief state, recommender output). Every number a user
 * reads here is rendered from state — the wording is varied prose, the facts are never generated by a model.
 */

export const GOAL_LABEL: Record<Goal, string> = {
  WEIGHT_LOSS: "giảm mỡ",
  MUSCLE_GAIN: "tăng cơ",
  MAINTENANCE: "duy trì",
  ATHLETIC_PERFORMANCE: "nâng cao hiệu suất thể thao",
};

const kg = (n: number) => `${String(Math.round(n * 10) / 10).replace(".", ",")}kg`;

export function directionClarification(p: { goal: Goal; currentKg: number; targetKg: number; direction: "BELOW" | "ABOVE" }): string {
  const cmp = p.direction === "BELOW" ? "thấp hơn" : "cao hơn";
  const alt = p.direction === "BELOW"
    ? `(1) giảm xuống ${kg(p.targetKg)} — mình sẽ đề xuất đổi mục tiêu chính sang giảm mỡ, hoặc (2) vẫn ${GOAL_LABEL[p.goal]} với một mức cao hơn ${kg(p.currentKg)}`
    : `(1) đặt ${kg(p.targetKg)} — mình sẽ đề xuất đổi mục tiêu chính sang tăng cơ, hoặc (2) vẫn ${GOAL_LABEL[p.goal]} với một mức thấp hơn ${kg(p.currentKg)}`;
  return `Mức ${kg(p.targetKg)} ${cmp} cân nặng hiện tại của bạn (${kg(p.currentKg)}), trong khi mục tiêu đang lưu là ${GOAL_LABEL[p.goal]}. Bạn muốn ${alt}? Nếu chưa chắc, bạn cứ nhờ mình đề xuất một mức phù hợp.`;
}

export function goalChangePreface(p: { from: Goal; to: Goal; currentKg?: number; targetKg?: number }): string {
  const move = p.currentKg !== undefined && p.targetKg !== undefined ? ` Bạn hiện nặng ${kg(p.currentKg)} và muốn xuống khoảng ${kg(p.targetKg)}, nên` : " Từ những gì bạn vừa nói,";
  return `Hiểu rồi — thông tin mới của bạn khác với mục tiêu ${GOAL_LABEL[p.from]} đang lưu.${move} có vẻ mục tiêu chính của bạn đã chuyển sang ${GOAL_LABEL[p.to]}. Mình chưa thay đổi gì cho tới khi bạn xác nhận; đây là thay đổi mình đề xuất:`;
}

/** "tại sao bạn nghĩ tôi nên giảm mỡ?" — explains from the user's OWN numbers; never diagnoses. */
export function whyGoalExplanation(p: { to: Goal; heightCm?: number; weightKg?: number }): string {
  if (p.heightCm && p.weightKg) {
    const h = p.heightCm / 100;
    const bmi = Math.round((p.weightKg / (h * h)) * 10) / 10;
    const bmiTxt = String(bmi).replace(".", ",");
    if (p.to === "WEIGHT_LOSS" && bmi >= 25) return `Mình dựa trên số liệu bạn đã lưu: ${p.heightCm}cm, ${kg(p.weightKg)} cho BMI khoảng ${bmiTxt}, cao hơn khoảng bình thường (18,5–24,9), nên giảm mỡ là một hướng hợp lý để cân nhắc. Đây chỉ là chỉ số tham khảo, không phải chẩn đoán.`;
    if (p.to === "WEIGHT_LOSS") return `Với ${p.heightCm}cm và ${kg(p.weightKg)} (BMI khoảng ${bmiTxt}, đang trong khoảng bình thường), giảm mỡ không phải điều bắt buộc theo chỉ số — nhưng nếu đó là điều bạn muốn thì mình vẫn có thể lập kế hoạch phù hợp.`;
  }
  return `Mình chỉ dựa trên điều bạn vừa nói (${GOAL_LABEL[p.to]}) chứ chưa kết luận gì về cơ thể bạn.`;
}

export function goalDroppedQuestion(dropped: Goal): string {
  return `Ok, mình sẽ không dùng mục tiêu ${GOAL_LABEL[dropped]} nữa. Bạn muốn chuyển sang giảm mỡ, duy trì hay hiệu suất thể thao? Hoặc bạn nhờ mình đề xuất theo chỉ số hiện tại của bạn.`;
}

export function recommendationText(r: Exclude<TargetWeightRecommendation, { kind: "INSUFFICIENT" }>, goalChange?: { from: Goal; to: Goal }): string {
  const i = r.inputs;
  const head = `Với chiều cao ${i.heightCm}cm và cân nặng ${kg(i.currentWeightKg)} (BMI khoảng ${String(r.bmiNow).replace(".", ",")}), `;
  if (r.kind === "GAIN_NOT_ADVISED" || r.kind === "MAINTAIN") {
    const note = r.note.charAt(0).toLowerCase() + r.note.slice(1);
    return `${head}${note} Bạn muốn mình đề xuất theo hướng khác (ví dụ giảm mỡ hoặc duy trì) không?`;
  }
  const steps = r.checkpoints.length > 1 ? `đi từng mốc ${r.checkpoints.map(kg).join(" → ")}` : `hướng tới ${kg(r.recommendedKg)}`;
  const pace = `khoảng ${String(r.weeklyRateKg).replace(".", ",")}kg/tuần, tức cỡ ${r.weeksToRecommended} tuần để tới ${kg(r.recommendedKg)}`;
  const change = goalChange ? ` Vì hướng này khác mục tiêu ${GOAL_LABEL[goalChange.from]} đang lưu, mình cũng sẽ đề xuất đổi mục tiêu chính sang ${GOAL_LABEL[goalChange.to]} — bạn vẫn là người xác nhận.` : "";
  return `${head}mình đề xuất ${steps} (${pace}). ${r.note}${change}\n\nBạn đồng ý dùng ${kg(r.recommendedKg)} làm mục tiêu không? Bạn cũng có thể chọn mốc thấp hơn/cao hơn hoặc nhập một con số khác.`;
}

export function insufficientRecommendation(missing: string[]): string {
  return `Để đề xuất một mức phù hợp, mình cần biết thêm ${missing.join(" và ")} của bạn. Bạn cho mình thông tin đó nhé — sau đó mình sẽ đề xuất cụ thể.`;
}

export function explainRecommendation(r: { inputs: Record<string, unknown>; recommended: number; note?: string; checkpoints?: number[] }): string {
  const i = r.inputs as { heightCm?: number; currentWeightKg?: number };
  const basis = i.heightCm && i.currentWeightKg ? `dựa trên chiều cao ${i.heightCm}cm và cân nặng ${kg(i.currentWeightKg)} của bạn` : "dựa trên dữ liệu hiện có của bạn";
  const steps = r.checkpoints && r.checkpoints.length > 1 ? ` Các mốc trung gian (${r.checkpoints.map(kg).join(", ")}) giúp bạn giảm dần thay vì một bước lớn.` : "";
  return `Mình đề xuất ${kg(r.recommended)} ${basis}, theo nguyên tắc giữ tốc độ thay đổi vừa phải và không xuống dưới ngưỡng BMI bình thường.${steps} Đây là gợi ý để bạn cân nhắc, không phải chẩn đoán hay cam kết kết quả — bạn có thể chọn mức khác.`;
}

export function countRecommendation(label: string, value: number, reason: string): string {
  return `Với thông tin hiện tại, mình đề xuất ${label} là ${value} (${reason}). Bạn đồng ý mức này không, hay muốn chọn con số khác?`;
}

export function negatedValueQuestion(rejected: string, ask: string): string {
  return `Ok, mình bỏ mức ${rejected}. ${ask}`;
}

export function nothingProposedYet(): string {
  return "Mình chưa đề xuất mức nào trước đó để bạn chọn. Bạn cho mình một con số, hoặc nhờ mình đề xuất nhé.";
}

export function middleAmbiguous(options: number[]): string {
  return `Hiện mình mới có ${options.length} mức (${options.map(kg).join(" và ")}), nên chưa có "mức giữa" rõ ràng. Bạn chọn mức thấp hơn, cao hơn, hay nhập một con số khác?`;
}
